SQL_DOC.P_SQL:
DECLARE
V_COUNT NUMBER;
BEGIN
V_COUNT := 0;
SELECT COUNT(*) INTO V_COUNT FROM PURCHASE_TMP WHERE PLAN = $PLANT$ AND LEGACY_PO_NO = $LEGACY_PO_NO$ AND LEGACY_PO_SEQ= $LEGACY_PO_SEQ$ ;
IF V_COUNT=0 THEN
INSERT INTO PURCHASE_TMP ( PLAN, LEGACY_PO_NO, LEGACY_PO_SEQ, STATUS, ACC_CD, MAC_CD, DEPT_CD, BUYER_ITEM_NO, DESCRIPTION, SPECIFICATION, QUN, UNIT_ID, AMT, BIGO )VALUES ( $PLANT$ , $LEGACY_PO_NO$ , $LEGACY_PO_SEQ$ , $STATUS$ , $ACC_CD$ , $MAC_CD$ , $DEPT_CD$ , $BUYER_ITEM_NO$ , $DESCRIPTION$ , $SPECIFICATION$ , $ITEM_QTY$ , $UNIT_MEASURE$ , $ITEM_AMT$ , $REMARK$ );
ELSE
UPDATE PURCHASE_TMP SET STATUS = $STATUS$ , ACC_CD = $ACC_CD$ , MAC_CD = $MAC_CD$ , DEPT_CD= $DEPT_CD$ , QUN = $ITEM_QTY$ , AMT = $ITEM_AMT$ , BIGO = $REMARK$ ' WHERE PLAN = $PLANT$ AND LEGACY_PO_NO = $LEGACY_PO_NO$ AND LEGACY_PO_SEQ= $LEGACY_PO_SEQ$ ;
END IF;
END;
